mapper.update:
UPDATE files
SET deleted_at = now()
WHERE workspace_uuid = #{workspaceUUID}
    AND uuid = #{fileUUID}
    AND deleted_at IS NULL

UPDATE files file
SET filename = #{params.Filename}, mime_type = #{params.MediaType},
detected_mime_type = #{params.DetectedMimeType}, size_bytes = #{params.SizeBytes},
metadata = CAST(#{params.Metadata} AS jsonb),
authorization_metadata = CAST(#{params.AuthorizationMetadata} AS jsonb),
tags = #{params.Tags}, downloadable = #{params.Downloadable}, md5 = #{params.MD5},
sha256 = #{params.SHA256}, s3_bucket = #{params.S3Bucket}, s3_key = #{params.S3Key},
s3_etag = #{params.S3ETag}, s3_version_id = #{params.S3VersionID}, deleted_at = NULL
WHERE file.workspace_uuid = #{params.WorkspaceUUID}
AND file.uuid = (
SELECT resource.file_uuid
FROM session_resources resource
WHERE resource.uuid = #{params.ResourceUUID}
AND resource.workspace_uuid = #{params.WorkspaceUUID}
AND resource.session_uuid = #{params.SessionUUID}
)

UPDATE files file
SET deleted_at = COALESCE(file.deleted_at, #{params.RetiredAt})
WHERE file.workspace_uuid = #{params.WorkspaceUUID}
AND file.uuid = (
SELECT resource.file_uuid
FROM session_resources resource
WHERE resource.uuid = #{params.ResourceUUID}
AND resource.workspace_uuid = #{params.WorkspaceUUID}
AND resource.payload IS NULL
)

UPDATE files file
SET deleted_at = COALESCE(file.deleted_at, #{params.Now})
WHERE file.workspace_uuid = #{params.WorkspaceUUID}
AND file.uuid IN (
SELECT resource.file_uuid
FROM session_resources resource
WHERE resource.workspace_uuid = #{params.WorkspaceUUID}
AND resource.session_uuid = #{params.SessionUUID}
AND resource.deleted_at IS NULL
AND resource.payload IS NULL
AND resource.resource_type = 'file'
AND (
resource.path = #{params.EntryPath}
OR left(resource.path, char_length(#{params.EntryPath}) + 1) = #{params.EntryPath} || '/'
)
)

UPDATE files file
SET deleted_at = #{params.Now}
WHERE file.workspace_uuid = #{params.WorkspaceUUID}
AND file.deleted_at IS NULL
AND file.uuid IN (
SELECT resource.file_uuid
FROM session_resources resource
WHERE resource.workspace_uuid = #{params.WorkspaceUUID}
AND resource.session_uuid = #{params.SessionUUID}
AND resource.resource_type = 'skill_archive'
AND resource.file_uuid IS NOT NULL
AND resource.deleted_at IS NULL
)
